static void audio_test_clip_write(struct audio_test_clip_s *clip,
                                  const struct ap_buffer_s *apb)
{
  size_t room;

  if (clip->settle > 0)
    {
      clip->settle--;
      return;
    }

  room = clip->capacity - clip->used;
  if (room == 0)
    {
      return;
    }

  if (apb->nbytes < room)
    {
      room = apb->nbytes;
    }

  memcpy(clip->data + clip->used, apb->samp, room);
  clip->used += room;
}

